public void setErrorPreviewMessage(){
  try {
    if (getActivity() != null) {
      Snackbar.make(binding.emptyListView, R.string.resized_image_not_possible_download, Snackbar.LENGTH_INDEFINITE).setAction(R.string.common_yes, v -> {
        PreviewImageActivity activity = (PreviewImageActivity) getActivity();
        if (activity != null) {
          activity.requestForDownload(getFile());
        } else if (getContext() != null) {
          Snackbar.make(binding.emptyListView, getResources().getString(R.string.could_not_download_image), Snackbar.LENGTH_INDEFINITE).show();
        }
      }).show();
    }
  } catch (IllegalArgumentException | NullPointerException | Resources.NotFoundException e) {
    Log_OC.d(TAG, e.getMessage());
  }
}
